insert into divisions(sport_id, name, slug, scoring_kind, scoring_config, standings_config, medal_policy, display_order) values ((select id from sports where slug='chess'), 'Boys', 'boys', 'simple', '{"allow_forfeit": true}'::jsonb, '{"order": ["win_pct", "wins", "head_to_head", "set_ratio", "point_ratio"], "show_draws": false, "standings_points": {"win": 3, "draw": 1, "loss": 0}}'::jsonb, '{"place_to_medal": {"1": "gold", "2": "silver", "3": "bronze"}, "max_per_medal": {"gold": 1, "silver": 1, "bronze": 1}, "shared_allowed": false}'::jsonb, 1) on conflict (sport_id, slug) do update set name = excluded.name;
